import { HugeiconsIcon } from "@hugeicons/react";
import ShieldAlertIcon from "@hugeicons/core-free-icons/ShieldAlertIcon";

import { Button } from "@/registry/erbium/ui/button";
import {
  Item,
  ItemActions,
  ItemContent,
  ItemDescription,
  ItemMedia,
  ItemTitle,
} from "@/registry/erbium/ui/item";

export default function ItemIcon() {
  return (
    <div className="flex w-full max-w-lg flex-col gap-section">
      <Item variant="card">
        <ItemMedia variant="icon">
          <HugeiconsIcon icon={ShieldAlertIcon} />
        </ItemMedia>
        <ItemContent>
          <ItemTitle>Security Alert</ItemTitle>
          <ItemDescription>New login detected from unknown device.</ItemDescription>
        </ItemContent>
        <ItemActions>
          <Button size="sm" variant="outline">
            Review
          </Button>
        </ItemActions>
      </Item>
    </div>
  );
}

import ExampleItemIcon from "../examples/item-icon";

const Example = () => (
  <div className="w-full min-w-72 max-w-2xl p-4">
    <ExampleItemIcon />
  </div>
);

export default Example;
